def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple, str, bytes)):
        return seq, type(seq)
    else:
        # If it's not a sequence type, try to convert it to a list
        try:
            seq_list = list(seq)
            return seq_list, list
        except TypeError:
            # If it's not iterable, wrap it in a list
            return [seq], list

