def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    from typing import Dict
    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except (json.JSONDecodeError, ValueError):
        pass

    # Try XRD (XML) format
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        result = {}
        # XRD format: <XRD xmlns="http://docs.oasis-open.org/webfinger/xrd">
        # Look for links
        for link in root.findall('.//{http://docs.oasis-open.org/webfinger/xrd}link'):
            rel = link.get('rel')
            href = link.get('href')
            if rel and href:
                result[rel] = href
        return result
    except Exception:
        pass

    return {}

